// Generating the short code
function generateShortCode(longUrl, counter) {
  // Option A: truncated URL hash (MD5/SHA) -> possible collisions
  // Option B: global counter encoded in base62 -> unique, but potential SPOF
  // Option C: pre-allocated ID range per server -> no SPOF, unique
  return encodeBase62(counter)
}

// Reading: the most traveled path
app.get('/:code', async (req, res) => {
  const longUrl = await cache.get(req.params.code)      // 1. cache first
  if (longUrl) return res.redirect(longUrl)

  const fromDb = await db.findByCode(req.params.code)     // 2. otherwise, database
  await cache.set(req.params.code, fromDb.longUrl)        // 3. fill the cache
  res.redirect(fromDb.longUrl)
})

// Fan-out on write: expensive for accounts with millions of followers
function onNewPost(post) {
  const followers = getFollowers(post.authorId)  // can be huge
  for (const followerId of followers) {
    pushToFeedCache(followerId, post)             // writes multiplied by N
  }
}

// Fan-out on read: simple to write, slower to read
function getFeed(userId) {
  const following = getFollowing(userId)
  const recentPosts = getRecentPostsFrom(following) // on-the-fly aggregation
  return sortByTime(recentPosts)
}

// Common hybrid approach in production
function onNewPost(post) {
  if (getFollowerCount(post.authorId) < CELEBRITY_THRESHOLD) {
    fanOutOnWrite(post)      // normal accounts: immediate push
  }
  // "celebrity" accounts: fan-out on read at read time
}

// Sharding: splitting users across several databases
function getShardForUser(userId, shardCount) {
  return hash(userId) % shardCount   // same user -> always the same shard
}

// Consequence: a simple query stays fast
const shard = getShardForUser(userId, 8)
db[shard].findUser(userId)             // only 1 database queried

// But a cross-user query becomes expensive
function getTopUsersGlobally() {
  const results = []
  for (const shard of allShards) {
    results.push(...shard.query('ORDER BY score DESC LIMIT 10'))
  }
  return mergeAndSort(results)          // manual aggregation across shards
}

// Token bucket: simplified implementation
class TokenBucket {
  constructor(capacity, refillRatePerSec) {
    this.capacity = capacity
    this.tokens = capacity
    this.refillRate = refillRatePerSec
    this.lastRefill = Date.now()
  }

  allow() {
    this.refill()
    if (this.tokens >= 1) {
      this.tokens -= 1
      return true          // request accepted
    }
    return false            // 429 Too Many Requests
  }

  refill() {
    const now = Date.now()
    const elapsedSec = (now - this.lastRefill) / 1000
    this.tokens = Math.min(this.capacity, this.tokens + elapsedSec * this.refillRate)
    this.lastRefill = now
  }
}

// Assigning a key to a server on the ring
function getServerForKey(key, servers) {
  const keyPos = hash(key) % RING_SIZE
  const sorted = [...servers].sort((a, b) => a.pos - b.pos)

  // first server whose position is >= the key's position
  const target = sorted.find((s) => s.pos >= keyPos)

  return target || sorted[0]   // wrap back to the start of the ring if none found
}

// Virtual nodes: each physical server occupies SEVERAL positions
function addServerWithVirtualNodes(server, virtualCount, ring) {
  for (let i = 0; i < virtualCount; i++) {
    ring.push({ id: server.id, pos: hash(server.id + '-' + i) % RING_SIZE })
  }
}
